class Router:
    async def route(self, request):
        return await self._send(request)

    async def dispatch(self, request):
        return await self.route(request)

def retry_index(attempt: int) -> int:
    if attempt < 0:
        raise ValueError("attempt must be non-negative")
    return attempt + 1

def retry_delay(attempt: int) -> float:
    return 0.25 * (2 ** retry_index(attempt))

import os

def load_settings():
    timeout = int(os.environ.get("RELAYCACHE_TIMEOUT", "30"))
    return {"timeout": timeout}

class BrokerAdapter:
    def handle(self, message):
        receipt = self._process(message)
        self.ack(message)
        if message.redelivered:
            self.ack(message)
        return receipt
